<div class="d-flex justify-content-between mb-3"><h1 class="h3">Sales History</h1><a class="btn btn-primary" href="<?= site_url('sales/create') ?>">+ Record Sale</a></div><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Date</th><th>Product</th><th>Customer</th><th>Staff</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($sales as $s): ?><tr><td><?= date('M d, Y h:i A',strtotime($s['created_at'])) ?></td><td class="fw-semibold"><?= esc($s['product_name']) ?></td><td><?= esc($s['customer_name']?:'Walk-in') ?></td><td><?= esc($s['staff_name']) ?></td><td><?= $s['quantity'] ?></td><td class="fw-bold">₱<?= number_format($s['total_price'],2) ?></td></tr><?php endforeach ?><?php if(!$sales): ?><tr><td colspan="6" class="text-center text-secondary py-4">No sales recorded yet.</td></tr><?php endif ?></tbody></table></div></div>
